17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        // Normalize the telephone on create: strip every non-digit character so it is stored and
106	        // returned as the bare 10-digit value. Bean validation on OwnerFieldsDto has already
107	        // guaranteed exactly 10 digits are present (rejecting anything else with 400).
108	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
109	        owner.setTelephone(normalizedTelephone);
110	        // Reject creating an owner whose normalized telephone is already used by another owner.
111	        if (isTelephoneInUse(normalizedTelephone)) {
112	            throw new DuplicateTelephoneException(
113	                "An owner with telephone " + normalizedTelephone + " already exists");
114	        }
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    /**
123	     * Removes every non-digit character from the supplied telephone value.
124	     *
125	     * @param telephone the raw telephone value (may be {@code null})
126	     * @return the telephone stripped down to its digits, or {@code null} if the input was {@code null}
127	     */
128	    private String normalizeTelephone(String telephone) {
129	        return telephone == null ? null : telephone.replaceAll("\\D", "");
130	    }
131	
132	    /**
133	     * Determines whether the given normalized telephone is already used by an existing owner.
134	     * Stored telephones are normalized before comparison so values that differ only in
135	     * formatting (spaces, dashes, parentheses) are treated as the same number.
136	     *
137	     * @param normalizedTelephone the normalized (digits-only) telephone to look for
138	     * @return {@code true} if another owner already uses this telephone
139	     */
140	    private boolean isTelephoneInUse(String normalizedTelephone) {
141	        if (normalizedTelephone == null) {
142	            return false;
143	        }
144	        return this.clinicService.findAllOwners().stream()
145	            .map(Owner::getTelephone)
146	            .map(this::normalizeTelephone)
147	            .anyMatch(normalizedTelephone::equals);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
